var renderer=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).First(r=>r.name=="Sprout");return renderer.transform.parent.GetComponentsInChildren<UnityEngine.Renderer>(true).Select(r=>new{name=r.name,enabled=r.enabled,position=r.transform.position.ToString(),materials=r.sharedMaterials.Where(m=>m!=null).Select(m=>new{name=m.name,shader=m.shader.name,path=UnityEditor.AssetDatabase.GetAssetPath(m)}).ToArray()}).ToArray();
